{
  "note_claim": "The House of Commons Library states there is no basis in council tax law for exempting domestic properties used for religious purposes.",
  "label": "SUPPORTS",
  "quote": "\"These claims have no basis in council tax law. It is not possible for owners of domestic property to avoid council tax by claiming that their property, or part of it, is used for religious purposes.\"",
  "reason": "The page explicitly contains the exact House of Commons Library quote cited in the note and confirms the claim is false."
}
